package org.telegram.messenger;

import android.Manifest;
import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.PendingIntent;
import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.pm.PackageManager;
import android.os.Build;

import androidx.core.content.ContextCompat;

import org.telegram.ui.LaunchActivity;

/** Notifications generated by the local Folder 42 archive. */
public final class Folder42Notifications {
    private static final String PREFS = "folder42_notifications";
    private static final String KEY_ENABLED = "enabled";
    private static final String CHANNEL_ID = "folder42_events";

    private Folder42Notifications() {
    }

    public static boolean areEnabled(Context context) {
        return preferences(context).getBoolean(KEY_ENABLED, true);
    }

    public static void setEnabled(Context context, boolean enabled) {
        preferences(context).edit().putBoolean(KEY_ENABLED, enabled).apply();
    }

    public static void notifyMessageChanged(Context context, String chatTitle, boolean deleted,
                                            long dialogId, int messageId) {
        if (context == null || !areEnabled(context)) {
            return;
        }
        if (Build.VERSION.SDK_INT >= 33 &&
                ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS)
                        != PackageManager.PERMISSION_GRANTED) {
            return;
        }

        NotificationManager manager = (NotificationManager) context.getSystemService(Context.NOTIFICATION_SERVICE);
        if (manager == null) {
            return;
        }
        createChannel(manager);

        String safeTitle = chatTitle == null || chatTitle.trim().isEmpty() ? "Переписка" : chatTitle;
        String eventTitle = deleted ? "Сообщение удалено" : "Сообщение отредактировано";
        String text = deleted
                ? "В чате «" + safeTitle + "» удалили сообщение"
                : "В чате «" + safeTitle + "» изменили сообщение";

        Intent intent = new Intent(context, LaunchActivity.class);
        intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP);
        intent.putExtra("folder42_open", true);
        intent.putExtra("folder42_dialog_id", dialogId);
        intent.putExtra("folder42_message_id", messageId);
        int requestCode = (int) (dialogId ^ (dialogId >>> 32)) ^ messageId;
        PendingIntent pendingIntent = PendingIntent.getActivity(context, requestCode, intent,
                PendingIntent.FLAG_UPDATE_CURRENT | (Build.VERSION.SDK_INT >= 23 ? PendingIntent.FLAG_IMMUTABLE : 0));

        Notification.Builder builder = Build.VERSION.SDK_INT >= 26
                ? new Notification.Builder(context, CHANNEL_ID)
                : new Notification.Builder(context);
        Notification notification = builder
                .setSmallIcon(android.R.drawable.ic_dialog_info)
                .setContentTitle("Папка № 42")
                .setContentText(text)
                .setStyle(new Notification.BigTextStyle().bigText(text))
                .setContentIntent(pendingIntent)
                .setAutoCancel(true)
                .setCategory(Notification.CATEGORY_STATUS)
                .setPriority(Notification.PRIORITY_HIGH)
                .build();
        manager.notify("folder42_" + dialogId, requestCode, notification);
    }

    private static void createChannel(NotificationManager manager) {
        if (Build.VERSION.SDK_INT >= 26 && manager.getNotificationChannel(CHANNEL_ID) == null) {
            NotificationChannel channel = new NotificationChannel(CHANNEL_ID, "Папка № 42",
                    NotificationManager.IMPORTANCE_HIGH);
            channel.setDescription("Уведомления об удалении и редактировании сообщений");
            manager.createNotificationChannel(channel);
        }
    }

    private static SharedPreferences preferences(Context context) {
        return context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
    }
}
